index c5f46d0..970adc4 100644
--- a/orchagent/intfsorch.cpp
+++ b/orchagent/intfsorch.cpp
@@ -1017,7 +1017,7 @@ bool IntfsOrch::removeRouterIntfs(Port &port)

     if (m_syncdIntfses[port.m_alias].ref_count > 0)
     {
